struct PendingChange {
    std::string origin;
    std::string operation;
    std::string credential;
    std::string next_token;
    std::string next_recovery;
    std::uint64_t expected_player_id = 0;
};

inline bool valid_pending(const PendingChange& p) {
    if (p.origin.empty() || !p.expected_player_id ||
        !study_credentials::valid_account(p.next_token) || !valid_recovery(p.next_recovery)) return false;
    if (p.operation == "recover") return valid_recovery(p.credential) && p.credential != p.next_recovery;
    if (!study_credentials::valid_account(p.credential)) return false;
    if (p.operation == "backup") return p.credential == p.next_token;
    if (p.operation == "rotate") return p.credential != p.next_token;
    return false;
}

bool begin(const PendingChange& p) const {
    if (p.origin!=origin_ || !valid_pending(p) || load_pending().state!=JournalRead::missing) return false;
    return write("change.pending.json",pending_json(p));
}

if (!reply) return {};
if (reply->status==400 || reply->status==401 || reply->status==409)
    return {RemoteState::rejected,0,0};
if (reply->status!=200) return {};
const auto j=object(reply->body,2);
if (!j) return {};
const auto id=number(*j,"player_id"),epoch=number(*j,"auth_epoch");
if (!id || !*id || !epoch || *epoch>static_cast<std::uint64_t>(std::numeric_limits<std::int64_t>::max())) return {};
return {RemoteState::accepted,*id,*epoch};

have_pending = true;
const PendingChange request = loaded.request;

// Replay the stored request exactly once; no candidates are generated.
RemoteChange remote = api.change(request);

try {
    if (!store.save_recovery(request, remote.player_id))
        return {JournalState::local_incomplete, 0};
    if (!store.save_access(request, remote.player_id))
        return {JournalState::local_incomplete, 0};
    if (!store.remove_pending())
        return {JournalState::local_incomplete, 0};
} catch (...) {
    return {JournalState::local_incomplete, 0};
}

const auto pending = read_local_document(file_.parent_path()/"change.pending.json");
if (pending.state != LocalRead::missing &&
    !(pending.state == LocalRead::ready && idle_journal(pending.body,origin_)))
    return {AccountLoad::invalid,{}};
const auto document = read_local_document(file_);
if (document.state == LocalRead::missing &&
    read_local_document(file_.parent_path()/"recovery.json").state != LocalRead::missing)
    return {AccountLoad::invalid,{}};
if (document.state == LocalRead::missing) return {AccountLoad::missing, {}};
